/**
 * 組 Modbus RTU 讀取指令（0x03 / Holding Register）
 */

const deviceID = msg.deviceID;

// 參數
const FUNCTION_CODE = 0x03;
const START_ADDRESS = 2090;
const QUANTITY = 4;

// [Addr, Func, StartHi, StartLo, QtyHi, QtyLo]
msg.payload = Buffer.from([
    deviceID,
    FUNCTION_CODE,
    (START_ADDRESS >> 8) & 0xff,
    START_ADDRESS & 0xff,
    (QUANTITY >> 8) & 0xff,
    QUANTITY & 0xff,
]);

return msg;

/**
 * 組 Modbus RTU 讀取指令（0x03 / Holding Register）
 */

const deviceID = msg.deviceID;

// 參數
const FUNCTION_CODE = 0x03;
const START_ADDRESS = 2090;
const QUANTITY = 4;  // 修改為 4 個寄存器以支持雙色溫

// [Addr, Func, StartHi, StartLo, QtyHi, QtyLo]
msg.payload = Buffer.from([
    deviceID,
    FUNCTION_CODE,
    (START_ADDRESS >> 8) & 0xff,
    START_ADDRESS & 0xff,
    (QUANTITY >> 8) & 0xff,
    QUANTITY & 0xff,
]);

return msg;

/**
 * 單色溫（single）控制：產生 Modbus 指令
 */

const DEFAULT_BRIGHTNESS = 100;
const BRIGHTNESS_TIME = 0x05;

const CHANNEL_REGISTER_MAP = {
    "1": 0x082A,
    "2": 0x082B,
    "3": 0x082C,
    "4": 0x082D,
};

// === Topic 解析與檢查 ===
const topic = String(msg.topic || "");
const parts = topic.split("/");

if (parts.length !== 6) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "single") return null;
if (parts[5] !== "set") return null;

const slaveId = Number(parts[3]);
const channel = parts[4];

if (!Number.isInteger(slaveId) || slaveId <= 0) return null;

const reg = CHANNEL_REGISTER_MAP[channel];
if (!reg) return null;

// === 從 device 配置中取得最低亮度 ===
const device = msg.devices.find(d => d.module_id == slaveId && d.channel == channel);
const brightMinimum = device ? (device.bright_minimum || 0) : 0;

// === 解析 payload（只接受 "ON" / "OFF"）===
if (typeof msg.payload !== "string") return null;

const state = msg.payload.toUpperCase();
if (state !== "ON" && state !== "OFF") return null;

const isOn = (state === "ON");

// === 亮度處理（使用快取，沒有則用預設）===
const brightnessKey = `single_${slaveId}_${channel}_brightness`;

let brightness = flow.get(brightnessKey);
if (typeof brightness !== "number") brightness = DEFAULT_BRIGHTNESS;

// 應用最低亮度限制
brightness = Math.max(brightMinimum, brightness);

brightness = Math.min(100, Math.max(0, brightness));
const value = isOn ? brightness : 0x00;

// === 組 Modbus 指令（0x06 Write Single Register）===
const regHi = (reg >> 8) & 0xFF;
const regLo = reg & 0xFF;

msg.payload = Buffer.from([
    slaveId,
    0x06,
    regHi,
    regLo,
    BRIGHTNESS_TIME,
    value,
]);

return msg;

/**
 * 雙色溫（dual）控制：產生兩筆 Modbus 指令
 */

const DEFAULT_BRIGHTNESS = 100; // 0~100
const DEFAULT_COLORTEMP = 250;  // mired
const MIN_MIRED = 154;
const MAX_MIRED = 370;
const DIMMING_SPEED = 0x05;

const CHANNEL_REGISTER_MAP = {
    a: [0x082A, 0x082B], // brightness, colortemp
    b: [0x082C, 0x082D],
};

function buildCommand(slaveId, reg, value) {
    const regHi = (reg >> 8) & 0xFF;
    const regLo = reg & 0xFF;

    return Buffer.from([
        slaveId,
        0x06,
        regHi,
        regLo,
        DIMMING_SPEED,
        value,
    ]);
}

// === Topic 檢查 ===
const parts = String(msg.topic || "").split("/");

if (parts.length !== 6) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "dual") return null;
if (parts[5] !== "set") return null;

const slaveId = Number(parts[3]);
const channel = String(parts[4] || "").toLowerCase();

if (!Number.isInteger(slaveId) || slaveId <= 0) return null;

const regs = CHANNEL_REGISTER_MAP[channel];
if (!regs) return null;

// === 從 device 配置中取得最低亮度和色溫範圍 ===
const device = msg.devices.find(d => d.module_id == slaveId && d.channel == channel);
const brightMinimum = device ? (device.bright_minimum || 0) : 0;
const colortempMinimum = device ? (device.colortemp_minimum || MIN_MIRED) : MIN_MIRED;
const colortempMaximum = device ? (device.colortemp_maximum || MAX_MIRED) : MAX_MIRED;

// === Payload（只接受 "ON" / "OFF"）===
if (typeof msg.payload !== "string") return null;

const state = msg.payload.toUpperCase();
if (state !== "ON" && state !== "OFF") return null;

const isOn = (state === "ON");

// === 讀取快取 ===
const brKey = `dual_${slaveId}_${channel}_brightness`;
const ctKey = `dual_${slaveId}_${channel}_colortemp`;

let brightness = flow.get(brKey);
if (typeof brightness !== "number") brightness = DEFAULT_BRIGHTNESS;
// 應用最低亮度限制
brightness = Math.max(brightMinimum, brightness);
brightness = Math.min(100, Math.max(0, Math.round(brightness)));

let colortemp = flow.get(ctKey);
if (typeof colortemp !== "number") colortemp = DEFAULT_COLORTEMP;
// 應用色溫範圍限制
colortemp = Math.min(colortempMaximum, Math.max(colortempMinimum, Math.round(colortemp)));

// === 數值轉換 ===
const brValue = isOn ? brightness : 0;

const ctPercent = Math.round(
    ((colortempMaximum - colortemp) / (colortempMaximum - colortempMinimum)) * 100
);

// === 產生兩筆指令 ===
const cmdBrightness = buildCommand(slaveId, regs[0], brValue);
const cmdColortemp = buildCommand(slaveId, regs[1], ctPercent);

node.send({ payload: cmdBrightness });
node.send({ payload: cmdColortemp });

return null;

// =======================================
// 收到回覆 → 解鎖（基於TCP動態管理）
// =======================================

// 1. 只要是 Buffer，就當作「有回覆」
if (!Buffer.isBuffer(msg.payload)) {
    return null;
}

// 2. 取得TCP標識符，預設為'_default'
const tcpId = msg.tcp || '_default';

// 3. 清掉 timeout（如果還存在）
const timer = flow.get(`currentTimeout${tcpId}`);
if (timer) {
    clearTimeout(timer);
    flow.set(`currentTimeout${tcpId}`, null);
}

// 4. 解鎖對應的TCP連接
global.set(`waitingReply${tcpId}`, false);

// 5. 狀態提示（方便你看流程在跑）
node.status({
    fill: "green",
    shape: "dot",
    text: `收到回覆，解鎖 ${tcpId}`
});

// 6. 主動觸發發送流程，送下一筆
msg.tcp = tcpId; // 確保TCP ID傳遞
return msg;

// =======================================
// 發送流程 + Timeout（基於TCP動態管理）
// =======================================

// 超時時間（ms）
// 建議實務值：600 ~ 1000
const TIMEOUT_MS = 800;

// 1. 取得TCP標識符，預設為'_default'
const tcpId = msg.tcp || '_default';

// 2. 取得對應TCP的佇列
let queue = global.get(`commandsQueue${tcpId}`);
if (!Array.isArray(queue) || queue.length === 0) {
  // 沒指令就什麼都不做
  return null;
}

// 3. 若正在等回覆 → 絕對不能再送
if (global.get(`waitingReply${tcpId}`)) {
  return null;
}

// 4. 取出 FIFO 第一筆
const cmd = queue.shift();
global.set(`commandsQueue${tcpId}`, queue);

// 5. 上鎖（代表「現在有一筆正在飛」）
global.set(`waitingReply${tcpId}`, true);

// 6. 設定 timeout：
//    無論發生什麼事，只要時間到就放行
const timer = setTimeout(() => {

  // 解除鎖定
  global.set(`waitingReply${tcpId}`, false);
  flow.set(`currentTimeout${tcpId}`, null);

  // 顯示狀態（方便現場 debug）
  node.status({
    fill: "yellow",
    shape: "ring",
    text: `timeout 放行 ${tcpId}`
  });

  // 主動觸發自己，再送下一筆
  node.send([null, { _kick: true, tcp: tcpId, reason: "timeout" }]);
}, TIMEOUT_MS);

// 記住 timer，讓「收到回覆」能清掉
flow.set(`currentTimeout${tcpId}`, timer);

// 7. 將指令送到 tcp out
//    注意：這裡只負責送，不關心結果
return { payload: cmd, tcp: tcpId };

