// =======================================
// 加入佇列（基於TCP動態管理）
// =======================================

// 1. 取得TCP標識符，預設為'_default'
const tcpId = msg.tcp || '_default';

// 2. 取得對應TCP的佇列（不存在就建立）
let queue = global.get(`commandsQueue${tcpId}`);
if (!Array.isArray(queue)) {
    queue = [];
}

// 3. 取得指令內容
//    預期是 Buffer；若是 Array 自動轉 Buffer
let cmd = msg.payload;
if (Array.isArray(cmd)) {
    cmd = Buffer.from(cmd);
}

// 4. 只接受 Buffer，其他型態直接忽略
if (!Buffer.isBuffer(cmd)) {
    return null;
}

// 5. 推進對應TCP的 FIFO 佇列
queue.push(cmd);
global.set(`commandsQueue${tcpId}`, queue);

// 6. 若目前沒有在等回覆，主動喚醒發送流程
//    payload 內容不重要，只是觸發用
if (!global.get(`waitingReply${tcpId}`)) {
    return { payload: null, tcp: tcpId };
}

// 7. 若正在等回覆，就單純入列，不再觸發
return null;

/**
 * CRC Builder - CRC16(Modbus)
 */

const payload = msg.payload;

if (!Buffer.isBuffer(payload)) return null;

const [crcLo, crcHi] = crc16Modbus(payload);

msg.payload = Buffer.concat([payload, Buffer.from([crcLo, crcHi])]);
return msg;

function crc16Modbus(buf) {
    let crc = 0xffff;

    for (let i = 0; i < buf.length; i++) {
        crc ^= buf[i];

        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xa001;
            else crc >>= 1;
        }
    }

    return [crc & 0xff, (crc >> 8) & 0xff];
}

/**
 * Sunwave Scene → Full Modbus Command Buffer
 *
 * === MQTT Topics ===
 *  Set Scene
 *    Topic   : homeassistant/scene/sunwave/set
 *    Payload : { "scene": 1~20, "group": 1~96 | "all" }
 *
 *  Save Scene
 *    Topic   : homeassistant/scene/sunwave/save
 *    Payload : { "scene": 1~20, "group": 1~96 | "all" }
 *
 * === Modbus Frame (no CRC) ===
 *  [0xFE, 0x06, 0x08, 0x20, VALUE_H, VALUE_L]
 */

node.status({});

const p = msg.payload || {};
const topic = String(msg.topic || "");

// ---------- 解析 ----------
let scene = Number(p.scene);
let group = p.group;

// 動作判斷（對應新 topic）
const isSave = topic.includes("/save");

// group 支援 all
if (group === "all" || group === "ALL") {
    group = 0xFF;
}
group = Number(group);

// ---------- 驗證 ----------
if (!Number.isInteger(scene) || scene < 1 || scene > 20) {
    node.status({ fill: "red", shape: "ring", text: "scene 必須是 1~20" });
    return null;
}

if (
    !Number.isInteger(group) ||
    !((group >= 1 && group <= 96) || group === 0xFF)
) {
    node.status({ fill: "red", shape: "ring", text: "group 必須是 1~96 或 ALL" });
    return null;
}

// ---------- 組 16-bit VALUE ----------
const actionBit = isSave ? 1 : 0;
const value =
    (actionBit << 15) |
    (scene << 8) |
    group;

// 拆高低位
const valueHi = (value >> 8) & 0xFF;
const valueLo = value & 0xFF;

// ---------- 組完整 Modbus Buffer ----------
msg.payload = Buffer.from([
    0xFE, // Device ID
    0x06, // Function Code
    0x08, // Register High (2080)
    0x20, // Register Low
    valueHi,
    valueLo
]);

// ---------- 狀態 ----------
node.status({
    fill: isSave ? "yellow" : "green",
    shape: "dot",
    text: `${isSave ? "Save" : "Set"} S${scene} G${group === 0xFF ? "ALL" : group}`
});

return msg;

/**
 * 色溫快取（dual / mired）
 */

const parts = String(msg.topic || "").split("/");

// homeassistant/light/dual/{id}/{channel}/set/colortemp
if (parts.length !== 7) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "dual") return null;
if (parts[5] !== "set") return null;
if (parts[6] !== "colortemp") return null;

const id = parts[3];
const channel = String(parts[4] || "").toLowerCase();

let mired = Number(msg.payload);
if (!Number.isFinite(mired)) return null;

mired = Math.max(154, Math.min(370, Math.trunc(mired))); // 2703 K ~ 6494 K

const key = `dual_${id}_${channel}_colortemp`;
flow.set(key, mired);

node.status({ fill: "blue", shape: "dot", text: `${key}=${mired}mired` });
return null;

let devices = msg.devices || [];

const LIGHT_TYPE_MAPPING = {
    single: {
        brightness: true,
        brightness_scale: 100,
        getExtra: (path) => ({
            brightness_state_topic: `homeassistant/light/${path}/brightness`,
            brightness_command_topic: `homeassistant/light/${path}/set/brightness`
        })
    },
    dual: {
        brightness: true,
        brightness_scale: 100,
        min_mireds: 154,
        max_mireds: 370,
        getExtra: (path) => ({
            brightness_state_topic: `homeassistant/light/${path}/brightness`,
            brightness_command_topic: `homeassistant/light/${path}/set/brightness`,
            color_temp_state_topic: `homeassistant/light/${path}/colortemp`,
            color_temp_command_topic: `homeassistant/light/${path}/set/colortemp`
        })
    },
    wrgb: {
        brightness: true,
        brightness_scale: 100,
        rgb: true,
        getExtra: (path) => ({
            brightness_state_topic: `homeassistant/light/${path}/brightness`,
            brightness_command_topic: `homeassistant/light/${path}/set/brightness`,
            rgb_state_topic: `homeassistant/light/${path}/rgb`,
            rgb_command_topic: `homeassistant/light/${path}/set/rgb`
        })
    },
    rgb: {
        brightness: true,
        brightness_scale: 100,
        rgb: true,
        getExtra: (path) => ({
            brightness_state_topic: `homeassistant/light/${path}/brightness`,
            brightness_command_topic: `homeassistant/light/${path}/set/brightness`,
            rgb_state_topic: `homeassistant/light/${path}/rgb`,
            rgb_command_topic: `homeassistant/light/${path}/set/rgb`
        })
    }
};

let msgs;

if (msg.action === "clear") {
    msgs = devices.map(dev => {
        let path = `${dev.type}/${dev.module_id}/${dev.channel}`;
        let uid = path.replaceAll("/", "_");
        return {
            topic: `homeassistant/light/${uid}/config`,
            payload: "",
            retain: false,
        };
    });
} else if (msg.action === "add") {
    // 原本 add 的流程
    msgs = devices.map(dev => {
        let path = `${dev.type}/${dev.module_id}/${dev.channel}`;
        let uid = path.replaceAll("/", "_");
        let topic = `homeassistant/light/${uid}/config`;
        let typeConfig = LIGHT_TYPE_MAPPING[dev.type] || {};
        let basePayload = Object.assign({//這邊是
            name: dev.name,
            unique_id: uid,
            object_id: uid,
            payload_on: "ON",
            payload_off: "OFF",
            optimistic: true,
            state_topic: `homeassistant/light/${path}/state`,
            command_topic: `homeassistant/light/${path}/set`
        }, typeConfig, typeConfig.getExtra ? typeConfig.getExtra(path) : {});
        delete basePayload.getExtra;
        return {
            topic,
            payload: JSON.stringify(basePayload),
            retain: false
        };
    });
}

return [msgs];

/**
 * 亮度快取（dual / 0~100）
 */

const parts = String(msg.topic || "").split("/");

// homeassistant/light/dual/{id}/{channel}/set/brightness
if (parts.length !== 7) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "dual") return null;
if (parts[5] !== "set") return null;
if (parts[6] !== "brightness") return null;

const id = parts[3];
const channel = String(parts[4] || "").toLowerCase();

let brightness = Number(msg.payload);
if (!Number.isFinite(brightness)) return null;

brightness = Math.max(0, Math.min(100, Math.trunc(brightness)));

const key = `dual_${id}_${channel}_brightness`;
flow.set(key, brightness);

node.status({ fill: "green", shape: "dot", text: `${key}=${brightness}` });
return null;

/**
 * 亮度快取（single / 0~100）
 */

const parts = String(msg.topic || "").split("/");

// homeassistant/light/single/{id}/{channel}/set/brightness
if (parts.length !== 7) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "single") return null;
if (parts[5] !== "set") return null;
if (parts[6] !== "brightness") return null;

const id = parts[3];
const channel = parts[4];

let brightness = Number(msg.payload);
if (!Number.isFinite(brightness)) return null;

brightness = Math.max(0, Math.min(100, Math.trunc(brightness)));

const key = `single_${id}_${channel}_brightness`;
flow.set(key, brightness);

node.status({ fill: "green", shape: "dot", text: `${key}=${brightness}` });
return null;

const p404 = new Set();
const p210 = new Set();
const source = msg.source || "polling";

msg.devices.map(device => {
    // node.warn(`${device.module_id}`);
    if (device.model === "p404") p404.add(device.module_id);
    else if (device.model === "p210") p210.add(device.module_id);
});

const p404_q = Array.from(p404, x => ({ deviceID: x, source: source }));
const p210_q = Array.from(p210, x => ({ deviceID: x, source: source }));

return [
    p404_q,
    p210_q,
];

/**
 * S402 4x DI 單擊解析
 *
 * Input:
 *   msg.payload = Buffer(8)
 *   [01, 06, 01, A0, index, flags, crcH, crcL]
 *
 * Output:
 *   msg.topic   = homeassistant/sensor/s402/di
 *   msg.payload = { id, di }
 */

let buf = msg.payload;

if (!Buffer.isBuffer(buf) || buf.length !== 8) return null;

// 解構（CRC 不用）
let [h1, h2, h3, cmd, index, flags] = buf;

// 判斷是否為 S402 DI 4x 封包
if (h1 !== 0x01 || h2 !== 0x06 || h3 !== 0x01 || cmd !== 0xA0) {
    return null;
}

flags &= 0xFF;          // in1 ~ in8
if (flags === 0) return null;

// 單擊事件：取第一個命中的 DI（1~8）
let di = 0;
for (let i = 0; i < 8; i++) {
    if (flags & (1 << i)) {
        di = i + 1;
        break;
    }
}
if (di === 0) return null;

msg.topic = "homeassistant/sensor/s402/di";
msg.payload = {
    id: index,
    di
};

node.status({
    fill: "green",
    shape: "dot",
    text: `s402 id=${index} di=${di}`
});

return msg;

// [01 06 01 A0 03 01 00 00]
msg.payload = Buffer.from([
    0x01, // header
    0x06,
    0x01,
    0xA0, // DI 4x
    0x03, // id = 3
    0x01, // 0000 0001 → DI1
    0x00, // crcH (ignore)
    0x00  // crcL
]);
return msg;

// DI2 + DI5（只會取 DI2）
msg.payload = Buffer.from([
    0x01,
    0x06,
    0x01,
    0xA0,
    0x01,
    0x12, // 0001 0010 → DI2 + DI5
    0x00,
    0x00
]);
return msg;

/**
 * 分流器：根據 msg.devices 中的 model 和 type 分流到對應的解析節點
 * 輸出 1: p404-single
 * 輸出 2: p404-dual
 * 輸出 3: p210-single
 * 輸出 4: p210-dual
 * 輸出 5: sunwave-scene
 */

// 來源檢查：只處理來自 feedback 的訊息
if (msg._source !== "feedback") return null;

// 防護檢查
if (!msg.payload || !Buffer.isBuffer(msg.payload)) return null;

// === 路由配置 ===
const DEVICE_ROUTES = {
    "p404-single": 0,
    "p404-dual": 1,
    "p210-single": 2,
    "p210-dual": 3
};

const SCENE_ROUTE = 4;

// === 工具函數 ===
function isSunwaveScene(buf) {
    return buf.length === 8 && 
           buf[0] === 0xFE && 
           buf[1] === 0x06 && 
           buf[2] === 0x08 && 
           buf[3] === 0x20;
}

function createRouteOutput(targetIndex) {
    const outputs = new Array(5).fill(null);
    outputs[targetIndex] = msg;
    return outputs;
