const DEFAULT_BRIGHTNESS = 100; // 0~100
const DEFAULT_COLORTEMP = 250;  // mired
const MIN_MIRED = 154;
const MAX_MIRED = 370;
const DIMMING_SPEED = 0x05;

const CHANNEL_REGISTER_MAP = {
    a: [0x01F4, 0x01F5], // brightness, colortemp
    b: [0x01F6, 0x01F7],
};

function buildCommand(slaveId, reg, value) {
    const regHi = (reg >> 8) & 0xFF;
    const regLo = reg & 0xFF;

    return Buffer.from([
        slaveId,
        0x06,
        regHi,
        regLo,
        DIMMING_SPEED,
        value,
    ]);
}

// === Topic 檢查 ===
const parts = String(msg.topic || "").split("/");

if (parts.length !== 6) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "dual") return null;
if (parts[5] !== "set") return null;

const slaveId = Number(parts[3]);
const channel = String(parts[4] || "").toLowerCase();

if (!Number.isInteger(slaveId) || slaveId <= 0) return null;

const regs = CHANNEL_REGISTER_MAP[channel];
if (!regs) return null;

// === 從 device 配置中取得最低亮度和色溫範圍 ===
const device = msg.devices.find(d => d.module_id == slaveId && d.channel == channel);
const brightMinimum = device ? (device.bright_minimum || 0) : 0;
const colortempMinimum = device ? (device.colortemp_minimum || MIN_MIRED) : MIN_MIRED;
const colortempMaximum = device ? (device.colortemp_maximum || MAX_MIRED) : MAX_MIRED;

// === Payload（只接受 "ON" / "OFF"）===
if (typeof msg.payload !== "string") return null;

const state = msg.payload.toUpperCase();
if (state !== "ON" && state !== "OFF") return null;

const isOn = (state === "ON");

// === 讀取快取 ===
const brKey = `dual_${slaveId}_${channel}_brightness`;
const ctKey = `dual_${slaveId}_${channel}_colortemp`;

let brightness = flow.get(brKey);
if (typeof brightness !== "number") brightness = DEFAULT_BRIGHTNESS;
// 應用最低亮度限制
brightness = Math.max(brightMinimum, brightness);
brightness = Math.min(100, Math.max(0, Math.round(brightness)));

let colortemp = flow.get(ctKey);
if (typeof colortemp !== "number") colortemp = DEFAULT_COLORTEMP;
// 應用色溫範圍限制
colortemp = Math.min(colortempMaximum, Math.max(colortempMinimum, Math.round(colortemp)));

// === 數值轉換 ===
const brValue = isOn ? brightness : 0;

const ctPercent = Math.round(
    ((colortempMaximum - colortemp) / (colortempMaximum - colortempMinimum)) * 100
);

// === 產生兩筆指令（不含 CRC）===
const cmdBrightness = buildCommand(slaveId, regs[0], brValue);
const cmdColortemp = buildCommand(slaveId, regs[1], ctPercent);

// 發送兩筆指令到下一個節點（CRC Builder）
node.send({ payload: cmdBrightness });
node.send({ payload: cmdColortemp });

return null;

